// https://github.com/EnCiv/civil-pursuit/issues/43
// https://github.com/EnCiv/civil-pursuit/issues/246
import React, { useState, useRef, useEffect } from 'react'
import { createUseStyles } from 'react-jss'
import { TooltipPortal } from './tooltip-portal'
import cx from 'classnames'

/**
 * Button component(without stretch goal version) that is styled using react-jss.
 * It supports various states like hover, active, and disabled,
 * and can be configured with custom styles, titles, and callbacks.
 *
 * @param {Object} props - The props for the Button component.
 */

function Button(props) {
  const {
    className = '', // may or may not be passed. Should be applied to the outer most tag, after local classNames
    onDone = () => {}, // a function that is called when the button is clicked.  - if it exists
    title = '', // text to display on hover
    disabled = false,
    tabIndex = 0,
    disableOnClick = false, // if true, the button gets disabled after click and stays disabled - prevents resubmission
    noPendingClick = false, // if true, clicking while disabled is silently dropped (not queued for later)
    value,
    type = 'button', // by default this is a button
    children,
    ...otherProps
  } = props
  const displayTime = Math.max(8, 0.1 * title.length) * 1000
  const [isDisabled, setIsDisabled] = useState(disabled)
  const [isPortalOpen, setIsPortalOpen] = useState(false)
  const downTimeStampRef = useRef(0) // useRef not useState: must be readable synchronously in handleMouseUp immediately after handleMouseDown sets it
  const [pendingClick, setPendingClick] = useState(false) // Tracks if a click occurred while disabled that should be executed when enabled. this was done for the Next button at the bottom of a step so that if the user fills out the input fields and then clicks Next after the next button is undisabled the click will still go through even if the button was disabled at the time of clicking
  const timeRef = useRef(null)
  const prevDisabledRef = useRef(disabled)

  const classes = buttonStyles()

  useEffect(() => {
    const wasDisabled = prevDisabledRef.current
    prevDisabledRef.current = disabled
    setIsDisabled(disabled)

    // If button transitions from disabled to enabled and there was a pending click, execute it
    if (wasDisabled && !disabled && pendingClick) {
      setPendingClick(false)
      onDone({ valid: true, value })
      if (disableOnClick) setIsDisabled(true)
    }
  }, [disabled, pendingClick, value, disableOnClick, onDone])

  const handleMouseDown = e => {
    e.stopPropagation()
    if (title) {
      timeRef.current = setTimeout(() => {
        setIsPortalOpen(true)
      }, 500)
    }
    downTimeStampRef.current = e.timeStamp
  }

  const handleMouseUp = e => {
    e.stopPropagation()
    if (timeRef.current) clearTimeout(timeRef.current)
    timeRef.current = null
    if (e.timeStamp - downTimeStampRef.current < 500) {
      // short click
      if (isDisabled) {
        // Button is disabled now but might become enabled after state updates
        if (!noPendingClick) setPendingClick(true)
      } else {
        onDone({ valid: true, value })
        if (disableOnClick) setIsDisabled(true)
      }
    }
  }

  const handleClick = e => {
    // Always stop click propagation. Button fires its action via onMouseDown/onMouseUp
    // (not onClick), so the native click event has no purpose once onDone has already
    // fired. Letting it bubble causes any parent onClick handler to fire unintentionally.
    e.stopPropagation()
    if (isDisabled) {
      e.preventDefault()
    }
  }

  const handleMouseLeave = e => {
    if (timeRef.current) clearTimeout(timeRef.current)
    timeRef.current = null
  }

  const handleKeyDown = e => {
    if (e.keyCode === 32 || e.key === ' ' || e.key === 'Spacebar' || e.key === 'Enter') {
      // Prevent page scroll on space and normalize keyboard activation behavior.
      e.preventDefault()
      e.stopPropagation()
      if (timeRef.current) clearTimeout(timeRef.current)
      timeRef.current = null
      if (disabled) {
        // Button is disabled now but might become enabled after state updates
        if (!noPendingClick) setPendingClick(true)
      } else {
        onDone({ valid: true, value })
        if (disableOnClick) setIsDisabled(true)
      }
    }
  }

  useEffect(() => {
    if (isPortalOpen) {
      const timeout = setTimeout(() => {
        setIsPortalOpen(false)
      }, displayTime)
      return () => clearTimeout(timeout)
    }
  }, [isPortalOpen, title.length])

  // TooltipPortal doesn't put a tag around the button, so className and other props can be applied to the Button
  return (
    <TooltipPortal isOpen={isPortalOpen} portalContent={<span>{title}</span>}>
      <button
        className={cx(classes.buttonBase, className)}
        tabIndex={tabIndex}
        title={title}
        aria-disabled={isDisabled}
        type={type}
        value={value}
        onMouseDown={handleMouseDown}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseLeave}
        onKeyDown={handleKeyDown}
        onClick={handleClick}
        {...otherProps}
      >
        {children}
      </button>
    </TooltipPortal>
  )
}

function ModifierButton(props) {
  const { className, ...otherProps } = props
  const classes = buttonStyles()
  return <Button {...otherProps} className={cx(classes.modifierButton, className)} />
}

function SecondaryButton(props) {
  const { className, ...otherProps } = props
  const classes = buttonStyles()
  return <Button {...otherProps} className={cx(classes.secondaryButton, className)} />
}

function PrimaryButton(props) {
  const { className, ...otherProps } = props
  const classes = buttonStyles()
  return <Button {...otherProps} className={cx(classes.primaryButton, className)} />
}

function TextButton(props) {
  const { className, ...otherProps } = props
  const classes = buttonStyles()
  return <Button {...otherProps} className={cx(classes.textButton, className)} />
}

const buttonStyles = createUseStyles(theme => ({
  buttonBase: {
    // These are common styles
    width: 'auto',
    height: 'auto',
    borderRadius: '0.5rem',
    padding: '0.75rem 1.25rem',
    fontFamily: `${theme.font.fontFamily}, sans-serif`,
    fontWeight: 600,
    fontSize: '1rem',
    lineHeight: '1.5rem',
    textAlign: 'center',
    transition: 'transform 160ms ease, box-shadow 160ms ease, background-color 160ms ease',
    '&:focus-visible': {
      outline: `${theme.focusOutline}`,
    },
    '&:not([aria-disabled="true"]):hover': {
      transform: 'translateY(-0.08rem)',
    },
    '&:active:not([aria-disabled="true"])': {
      transform: 'translateY(0.04rem)',
    },
    '&[aria-disabled="true"]': {
      transform: 'none',
    },
    '@media (prefers-reduced-motion: reduce)': {
      transition: 'none',
      '&:not([aria-disabled="true"]):hover, &:active:not([aria-disabled="true"])': {
        transform: 'none',
      },
    },
    // Add any other common styles here
  },

  secondaryButton: {
    extend: 'buttonBase',
    backgroundColor: theme.colors.white,
    color: theme.colors.primaryButtonBlue,
    border: `0.125rem solid ${theme.colors.primaryButtonBlue}`,
    boxShadow: '0 0.125rem 0 rgba(6, 51, 92, 0.14), 0 0.35rem 0.7rem rgba(6, 51, 92, 0.1)',

    '&[aria-disabled="true"]': {
      backgroundColor: theme.colors.white,
      color: theme.colors.disableGray,
      border: `0.125rem solid ${theme.colors.disableSecBorderGray}`,
      textDecoration: 'none',
      transition: 'none',
      cursor: 'not-allowed',
      pointerEvents: 'auto',
    },

    '&:hover, &.hover': {
      textDecoration: 'underline',
      textUnderlineOffset: '0.25rem',
      backgroundColor: theme.colors.white,
      borderColor: theme.colors.primaryButtonBlue,
    },

    '&.createhover': {
      backgroundColor: theme.colors.white,
      borderColor: theme.colors.primaryButtonBlue,
    },

    '&:active': {
      backgroundColor: theme.colors.primaryButtonBlue,
      color: theme.colors.white,
      border: `0.125rem solid ${theme.colors.primaryButtonBlue}`,
      textDecoration: 'none',
      boxShadow: 'inset 0 0.125rem 0.25rem rgba(0, 0, 0, 0.18)',
    },

    '&[aria-disabled="true"]:hover, &[aria-disabled="true"]:active': {
      textDecoration: 'none',
    },
  },

  modifierButton: {
    extend: 'buttonBase',
    backgroundColor: theme.colors.white,
    color: theme.colors.textBrown,
    border: `0.125rem solid ${theme.colors.encivYellow}`,
    boxShadow: '0 0.125rem 0 rgba(102, 68, 0, 0.14), 0 0.35rem 0.7rem rgba(102, 68, 0, 0.1)',

    '&:hover, &.hover': {
      textDecoration: 'underline',
      textUnderlineOffset: '0.25rem',
      backgroundColor: theme.colors.white,
      borderColor: theme.colors.encivYellow,
    },

    '&:active': {
      backgroundColor: theme.colors.encivYellow,
      color: theme.colors.textBrown,
      border: `0.125rem solid ${theme.colors.encivYellow}`,
      textDecoration: 'none',
    },
  },

  primaryButton: {
    extend: 'buttonBase',
    backgroundColor: theme.colors.primaryButtonBlue,
    color: theme.colors.white,
    border: `0.125rem solid ${theme.colors.primaryButtonBlue}`,
    boxShadow: '0 0.125rem 0 rgba(1, 23, 44, 0.28), 0 0.35rem 0.7rem rgba(6, 51, 92, 0.2)',

    '&[aria-disabled="true"]': {
      backgroundColor: theme.colors.borderGray,
      color: theme.colors.disableTextBlack,
      border: `0.0625rem solid ${theme.colors.borderGray}`,
      textDecoration: 'none',
      transition: 'none',
      cursor: 'not-allowed',
      pointerEvents: 'auto',
    },
    '&:not([aria-disabled="true"])': {
      '&:hover, &.hover': {
        textDecoration: 'underline',
        textUnderlineOffset: '0.25rem',
        backgroundColor: theme.colors.primaryButtonBlue,
        borderColor: theme.colors.primaryButtonBlue,
      },
    },
    '&:active:not([aria-disabled="true"])': {
      backgroundColor: theme.colors.mouseDownPrimeBlue,
      border: `0.125rem solid ${theme.colors.primaryButtonBlue}`,
      textDecoration: 'none',
      boxShadow: 'inset 0 0.125rem 0.25rem rgba(0, 0, 0, 0.2)',
    },
    '&[aria-disabled="true"]:hover, &[aria-disabled="true"]:active': {
      textDecoration: 'none',
    },
  },

  textButton: {
    extend: 'buttonBase',
    backgroundColor: 'transparent',
    color: theme.colors.title,
    border: 'none',
    textAlign: 'left',
    textDecoration: 'underline',
    textUnderlineOffset: '0.25rem',

    '&:hover, &.hover': {
      textDecoration: 'underline',
      textUnderlineOffset: '0.25rem',
      backgroundColor: 'transparent',
      borderColor: 'none',
    },

    '&:active': {
      color: theme.colors.title,
      textDecoration: 'none',
    },
  },
}))

export { Button, ModifierButton, SecondaryButton, PrimaryButton, TextButton }
